const tz = 'America/Fortaleza';
const agora = new Date();
const first = $input.first().json;

// ----- DATA (YYYY-MM-DD) e HORA (HH:MM:SS) no fuso -----
const dParts = new Intl.DateTimeFormat('pt-BR', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(agora);

const YYYY = dParts.find(p => p.type === 'year')?.value || '';
const MM = dParts.find(p => p.type === 'month')?.value || '';
const DD = dParts.find(p => p.type === 'day')?.value || '';

const data = `${YYYY}-${MM}-${DD}`;

const tParts = new Intl.DateTimeFormat('pt-BR', {
  timeZone: tz,
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
}).formatToParts(agora);

const HH = tParts.find(p => p.type === 'hour')?.value || '00';
const mm = tParts.find(p => p.type === 'minute')?.value || '00';
const ss = tParts.find(p => p.type === 'second')?.value || '00';

const hora = `${HH}:${mm}:${ss}`;

// ----- ID COLETA (AAMMDDHHMMSS) -----
const AA = YYYY.slice(-2);
const id_coleta = `${AA}${MM}${DD}${HH}${mm}${ss}`;

// ----- ÚLTIMA DATA COLETA (normaliza para YYYY-MM-DD) -----
const const_data_ultima_coletada = (first.data_utima_coleta ?? '').toString().trim();

function normalizaDataParaYYYYMMDD(s) {
  if (!s) return '';
  // já está em YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;

  // formato pt-BR: DD/MM/YYYY
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
    const [d, m, y] = s.split('/');
    return `${y}-${m}-${d}`;
  }

  // se vier com hora (ex: YYYY-MM-DDTHH:mm:ssZ), pega só a data
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) return s.slice(0, 10);

  return ''; // desconhecido
}

const ultimaDataNorm = normalizaDataParaYYYYMMDD(const_data_ultima_coletada);

// ----- REGRA: soma dia só se mudou o dia -----
const diaAtual = Number(first.dia || 0);
const mudouODia = ultimaDataNorm && ultimaDataNorm !== data;
const novoDia = mudouODia ? (diaAtual + 1) : diaAtual;

// ----- CAMPOS FIXOS/VAZIOS -----
const novaLinha = {
  id_paciente: (first.telefone ?? '').toString(),
  id_coleta,
  data,
  hora,
  dia: novoDia,

  pressao_Sis1: '',
  pressao_Dia1: '',
  pulsacao1: '',

  pressao_Sis2: '',
  pressao_Dia2: '',
  pulsacao2: '',

  pressao_Sis3: '',
  pressao_Dia3: '',
  pulsacao3: '',

  pressao_Sis_M: '',
  pressao_Dia_M: '',
  pulsacao_M: '',

  link_foto_drive: '',
  contexto_alim: '',
  contexto_sint: '',
  medicacao: '',
  atividade_fisi: '',
  stat_medi: 'coletando',
};

return [novaLinha];

// Transforma todos os items em um array de objetos
