// n8n Code node (JavaScript)
// Exige SIS/DIA/BPM (todos obrigatórios). Se qualquer um for null/ inválido -> reprova.

function extractJsonString(s) {
  if (typeof s !== 'string') return null;
  let t = s.trim();
  t = t.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
  const match = t.match(/\{[\s\S]*\}/);
  return match ? match[0] : null;
}

function safeParseLeitura(raw) {
  const js = extractJsonString(raw);
  if (!js) return { ok: false, err: 'Sem JSON detectável' };

  try {
    const obj = JSON.parse(js);

    const sis = obj.sis ?? obj.SIS ?? obj.sistolica ?? null;
    const dia = obj.dia ?? obj.DIA ?? obj.diastolica ?? null;
    const bpm = obj.bpm ?? obj.BPM ?? obj.pulse ?? obj.pulsacao ?? null;

    return {
      ok: true,
      sis: sis === null ? null : Number(sis),
      dia: dia === null ? null : Number(dia),
      bpm: bpm === null ? null : Number(bpm),
      evidence: obj.evidence ?? obj.evidencia ?? null
    };
  } catch (e) {
    return { ok: false, err: `JSON inválido: ${e.message}` };
  }
}

function isValidInt(x) {
  return Number.isInteger(x) && Number.isFinite(x);
}

function validateReadingStrict(r) {
  if (!r.ok) return { ok: false, err: r.err };

  // Agora: SIS/DIA/BPM são OBRIGATÓRIOS
  if (!isValidInt(r.sis) || !isValidInt(r.dia) || !isValidInt(r.bpm)) {
    return { ok: false, err: 'SIS/DIA/BPM ausentes ou não-inteiros' };
  }

  // Faixas (ajuste se quiser)
  if (r.sis < 70 || r.sis > 250) return { ok: false, err: 'SIS fora de faixa' };
  if (r.dia < 40 || r.dia > 150) return { ok: false, err: 'DIA fora de faixa' };
  if (r.bpm < 30 || r.bpm > 220) return { ok: false, err: 'BPM fora de faixa' };

  if (r.sis <= r.dia) return { ok: false, err: 'SIS <= DIA (inconsistente)' };

  return { ok: true };
}

const leituraA = safeParseLeitura($json.leituraA);
const leituraB = safeParseLeitura($json.leituraB);

const valA = validateReadingStrict(leituraA);
const valB = validateReadingStrict(leituraB);

// Se qualquer uma falhar: pede nova imagem
if (!valA.ok || !valB.ok) {
  const motivo = `Falha validação: A=${valA.ok ? 'ok' : valA.err} | B=${valB.ok ? 'ok' : valB.err}`;

  return [{
    ok: false,
    motivo,
    mensagem_paciente:
      "Não consegui ler sua pressão com segurança (incluindo o BPM) 😕\n\n" +
      "Envie outra foto bem de frente, aproximando a tela, sem reflexo/flash e com boa luz. " +
      "Se preferir, mande em texto: SIS/DIA e BPM."
  }];
}

// Se ambos válidos, compara (agora bpm sempre existe)
const matchSis = leituraA.sis === leituraB.sis;
const matchDia = leituraA.dia === leituraB.dia;
const matchBpm = leituraA.bpm === leituraB.bpm;

if (!(matchSis && matchDia && matchBpm)) {
  return [{
    ok: false,
    motivo: `Divergência A vs B: sis(${leituraA.sis} vs ${leituraB.sis}), dia(${leituraA.dia} vs ${leituraB.dia}), bpm(${leituraA.bpm} vs ${leituraB.bpm})`,
    mensagem_paciente:
      "As leituras não bateram entre si 😕\n\n" +
      "Por favor envie outra foto bem de frente e mais próxima da tela (sem reflexo/flash). " +
      "Se preferir, mande os valores em texto: SIS/DIA e BPM."
  }];
}

// OK: tudo preenchido e igual
return [{
  ok: true,
  sis: leituraA.sis,
  dia: leituraA.dia,
  bpm: leituraA.bpm,
  evidenceA: leituraA.evidence,
  evidenceB: leituraB.evidence,
  motivo: "Leituras A e B bateram e passaram validação (SIS/DIA/BPM obrigatórios)"
}];

// Cria um array com 5 variações da frase
const frases = [
  "Só um momento, estou registrando as informações.",
  "Aguarde um instante, estou registrando as informações no banco de dados.",
  "Um segundo, estou registrando as medições que você me passou.",
  "Por favor, só um momento enquanto registro as informações que me passou no banco de dados para análise.",
  "Só um instante."
];

// Escolhe aleatoriamente uma das frases
const fraseAleatoria = frases[Math.floor(Math.random() * frases.length)];

// Retorna o resultado como saída do nó
return [
  {
    json: {
      mensagem: fraseAleatoria
    }
  }
];

