// n8n Code node (JavaScript)
// Mode: Run Once for All Items

const items = $input.all();

// último item (linha mais recente)
const ultimo = items[items.length - 1]?.json ?? {};

return [
  {
    json: {
      id_paciente: ultimo.id_paciente ?? "",
      id_coleta: ultimo.id_coleta ?? "",
      data: ultimo.data ?? ""
    }
  }
];

// n8n Code node (JavaScript)
// Mode: "Run Once for All Items"
//
// Saída: apenas 1 variável (string)
// coletas_invalidadas = "2026-01-10 23:10:31 (PAS Δ=35)"  // ou várias separadas por \n
//
// Regras:
// variação PAS (max-min) >= PAS_TOL -> inválida
// variação PAD (max-min) >= PAD_TOL -> inválida
// (AGORA) considera TODAS as linhas recebidas (todas as datas)
// remove duplicatas (mesma data + mesma hora + mesmo Δ)

const PAS_TOL = 28;
const PAD_TOL = 18;

const items = $input.all();

function toNumber(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().replace(",", ".");
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

// Aceita: "DD/MM/AAAA" ou "AAAA-MM-DD" (e variações com hora depois)
function parseDateFlexible(raw) {
  if (!raw && raw !== 0) return null;

  if (raw instanceof Date && !Number.isNaN(raw.getTime())) return raw;

  if (typeof raw === "number") {
    // Google Sheets/Excel serial (dias desde 1899-12-30)
    const base = Date.UTC(1899, 11, 30);
    const dt = new Date(base + raw * 86400000);
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  const s = String(raw).trim();

  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    const y = Number(iso[1]), m = Number(iso[2]), d = Number(iso[3]);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  const br = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (br) {
    const d = Number(br[1]), m = Number(br[2]), y = Number(br[3]);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  const dt = new Date(s);
  return Number.isNaN(dt.getTime()) ? null : dt;
}

function dateKeyUTC(dt) {
  const y = dt.getUTCFullYear();
  const m = String(dt.getUTCMonth() + 1).padStart(2, "0");
  const d = String(dt.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function getHora(rowJson) {
  return String(rowJson.hora ?? rowJson.horario ?? rowJson["horário"] ?? "").trim();
}

function getMedicoes(rowJson) {
  const sis = [
    toNumber(rowJson.pressao_Sis1),
    toNumber(rowJson.pressao_Sis2),
    toNumber(rowJson.pressao_Sis3),
  ];
  const dia = [
    toNumber(rowJson.pressao_Dia1),
    toNumber(rowJson.pressao_Dia2),
    toNumber(rowJson.pressao_Dia3),
  ];
  return { sis, dia };
}

function deltaMaxMin(arr) {
  const vals = arr.filter(v => v !== null);
  if (vals.length < 2) return null;
  return Math.max(...vals) - Math.min(...vals);
}

// 1) Avaliar TODAS as linhas e guardar inválidas (com DEDUPE)
const invalSet = new Set(); // strings únicas

for (const it of items) {
  const j = it.json || {};

  const rawData = j.data ?? j.Data ?? j.DATA ?? j.date ?? j.Date;
  const dt = parseDateFlexible(rawData);
  const dkey = dt ? dateKeyUTC(dt) : "SEM-DATA";

  const hora = getHora(j) || "(hora não informada)";
  const { sis, dia } = getMedicoes(j);

  const dPAS = deltaMaxMin(sis);
  const dPAD = deltaMaxMin(dia);

  // Se não dá pra avaliar, considera inválida (qualidade ruim)
  if (dPAS === null || dPAD === null) {
    invalSet.add(`${dkey} ${hora} (dados insuficientes)`);
    continue;
  }

  const invalidaPAS = dPAS >= PAS_TOL;
  const invalidaPAD = dPAD >= PAD_TOL;

  if (invalidaPAS || invalidaPAD) {
    const partes = [];
    if (invalidaPAS) partes.push(`PAS Δ=${dPAS}`);
    if (invalidaPAD) partes.push(`PAD Δ=${dPAD}`);

    // DEDUPE por data + hora + conteúdo
    invalSet.add(`${dkey} ${hora} (${partes.join(", ")})`);
  }
}

// 2) Transformar em string única
const coletas_invalidadas = Array.from(invalSet).join("\n"); // uma por linha

return [{ json: { coletas_invalidadas } }];

// n8n Code node (JavaScript)
// Mode: "Run Once for All Items"
//
// Lê TODAS as linhas do Google Sheets (vários items),
// agrupa POR DIA (coluna "data"),
// e calcula métricas de cada dia usando:
// - pressao_Sis_M
// - pressao_Dia_M
// - pulsacao_M
// - hora (HH:MM ou HH:MM:SS)
//
// SAÍDA (somente strings, agregadas por dia e separadas por " | "):
// - media_dia
// - pct_acima_alvo
// - tendencia_diurna
// - pico_matinal_diurno
//
// ⚠️ Qualificadores clínicos importantes (aplicados nas métricas de tendência/pico):
// Estimativa com dados diurnos (sem medidas durante o sono);
// não permite classificar dipper/non-dipper nem surto matinal clássico.

// ======= AJUSTES / PARÂMETROS =======
const SYS_TARGET = 129; // normalidade: <129
const DIA_TARGET = 88;  // normalidade: <88

const DIPPER_MIN_DROP_PCT = 10; // queda noturna >=10% => dipper (regra clássica)

// ✅ "noite" = 18:00 até 22:59 (23:00 exclusivo)
const NIGHT_START_MIN = 18 * 60; // 18:00
const NIGHT_END_MIN   = 23 * 60; // 23:00 (exclusivo) => inclui 22:xx

const MORNING_START_MIN = 6 * 60;  // 06:00
const MORNING_END_MIN   = 11 * 60; // 11:00 (até 10:59)

const SURGE_SYS_DELTA = 15; // manhã pior que o resto por pelo menos 15 mmHg (PAS)
const SURGE_DIA_DELTA = 10; // ou 10 mmHg (PAD)

// ======= HELPERS =======
const items = $input.all();

function toNumber(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().replace(",", ".");
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

// Aceita: Date, número serial (Sheets/Excel), "YYYY-MM-DD..." ou "DD/MM/YYYY" (ou Date parseável)
function parseDateFlexible(raw) {
  if (!raw && raw !== 0) return null;

  if (raw instanceof Date && !Number.isNaN(raw.getTime())) return raw;

  if (typeof raw === "number") {
    // Google Sheets/Excel serial (dias desde 1899-12-30)
    const base = Date.UTC(1899, 11, 30);
    const dt = new Date(base + raw * 86400000);
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  const s = String(raw).trim();

  // YYYY-MM-DD (ou com hora depois)
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    const y = Number(iso[1]), m = Number(iso[2]), d = Number(iso[3]);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  // DD/MM/YYYY
  const br = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (br) {
    const d = Number(br[1]), m = Number(br[2]), y = Number(br[3]);
    const dt = new Date(Date.UTC(y, m - 1, d));
    return Number.isNaN(dt.getTime()) ? null : dt;
  }

  const dt = new Date(s);
  return Number.isNaN(dt.getTime()) ? null : dt;
}

function dateKeyUTC(dt) {
  const y = dt.getUTCFullYear();
  const m = String(dt.getUTCMonth() + 1).padStart(2, "0");
  const d = String(dt.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function parseTimeToMin(rawHora) {
  if (rawHora === null || rawHora === undefined || rawHora === "") return null;

  // Caso 1: Date
  if (rawHora instanceof Date && !Number.isNaN(rawHora.getTime())) {
    return rawHora.getHours() * 60 + rawHora.getMinutes();
  }

  // Caso 2: número (Sheets/Excel: fração do dia)
  if (typeof rawHora === "number" && Number.isFinite(rawHora)) {
    const totalMinutes = Math.round(rawHora * 24 * 60);
    const hh = Math.floor((totalMinutes / 60) % 24);
    const mm = totalMinutes % 60;
    return hh * 60 + mm;
  }

  // Caso 3: string "HH:MM" ou "HH:MM:SS"
  const s = String(rawHora).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (!m) return null;

  const hh = Number(m[1]), mm = Number(m[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return null;
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59) return null;

  return hh * 60 + mm;
}

// Janela que funciona tanto cruzando meia-noite quanto não
function inWindow(tmin, startMin, endMin) {
  if (tmin === null || tmin === undefined) return false;
  if (startMin < endMin) return (tmin >= startMin) && (tmin < endMin);
  return (tmin >= startMin) || (tmin < endMin);
}

function mean(arr) {
  const vals = arr.filter(v => v !== null);
  if (!vals.length) return null;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

function sd(arr) {
  const vals = arr.filter(v => v !== null);
  const n = vals.length;
  if (n < 2) return null;
  const mu = mean(vals);
  const varPop = vals.reduce((acc, x) => acc + (x - mu) ** 2, 0) / n;
  return Math.sqrt(varPop);
}

function minMaxDelta(arr) {
  const vals = arr.filter(v => v !== null);
  if (!vals.length) return null;
  const min = Math.min(...vals);
  const max = Math.max(...vals);
  return { min, max, delta: max - min };
}

function fmt1(n) {
  if (n === null || n === undefined || !Number.isFinite(n)) return "—";
  return String(Math.round(n * 10) / 10);
}
function fmt0(n) {
  if (n === null || n === undefined || !Number.isFinite(n)) return "—";
  return String(Math.round(n));
}

// ======= 1) Normalizar linhas e agrupar por data =======
const grouped = new Map(); // dateKey -> rows[]

for (const it of items) {
  const rawData = it.json.data ?? it.json.Data ?? it.json.DATA;
  const dt = parseDateFlexible(rawData);
  if (!dt) continue;

  const key = dateKeyUTC(dt);

  const horaRaw = it.json.hora ?? it.json.horario ?? it.json.horário ?? "";
  const hora = String(horaRaw).trim();
  const tmin = parseTimeToMin(horaRaw instanceof Date ? horaRaw : hora);

  const sis = toNumber(it.json.pressao_Sis_M ?? it.json.pressao_Sis ?? it.json.PAS ?? it.json.sis);
  const dia = toNumber(it.json.pressao_Dia_M ?? it.json.pressao_Dia ?? it.json.PAD ?? it.json.dia);
  const pul = toNumber(it.json.pulsacao_M ?? it.json.pulsacao ?? it.json.pulso ?? it.json.puls);

  // exige PAS e PAD válidas
  if (sis === null || dia === null) continue;

  const row = { hora, tmin, sis, dia, pul };
  if (!grouped.has(key)) grouped.set(key, []);
  grouped.get(key).push(row);
}

if (!grouped.size) {
  return [{
    json: {
      media_dia: "Sem dados válidos (coluna 'data' + PAS/PAD) para analisar.",
      pct_acima_alvo: "",
      tendencia_diurna: "",
      pico_matinal_diurno: "",
    }
  }];
}

// ordenar datas
const dateKeys = Array.from(grouped.keys()).sort(); // YYYY-MM-DD ordena lexicograficamente OK

// ======= 2) Processar cada dia e montar strings agregadas =======
const mediaParts = [];
const pctParts = [];
const tendenciaParts = [];
const picoParts = [];

const circadianQualifier =
  "Estimativa com dados diurnos (sem medidas durante o sono); " +
  "não permite classificar dipper/non-dipper clássico.";

const surgeQualifier =
  "Estimativa com dados diurnos (sem medidas durante o sono); " +
  "não permite calcular surto matinal clássico (sleep-trough ou pré-despertar).";

for (const key of dateKeys) {
  const rows = grouped.get(key) || [];
  if (!rows.length) continue;

  const sisArr = rows.map(r => r.sis);
  const diaArr = rows.map(r => r.dia);
  const pulArr = rows.map(r => r.pul);

  const sisMean = mean(sisArr);
  const diaMean = mean(diaArr);
  const pulMean = mean(pulArr);

  const sisMM = minMaxDelta(sisArr);
  const diaMM = minMaxDelta(diaArr);

  const sisSD = sd(sisArr);
  const diaSD = sd(diaArr);

  // ---- media_dia (por data)
  const media_dia_day =
    `Data ${key} — Média do dia: ` +
    `PAS ${fmt1(sisMean)} | PAD ${fmt1(diaMean)} | Puls ${fmt1(pulMean)}. ` +
    `Variabilidade: PAS Δ=${fmt0(sisMM?.delta)} (SD=${fmt1(sisSD)}), ` +
    `PAD Δ=${fmt0(diaMM?.delta)} (SD=${fmt1(diaSD)}).`;
  mediaParts.push(media_dia_day);

  // ---- pct_acima_alvo (por data)
  const total = rows.length;
  const above = rows.filter(r => (r.sis >= SYS_TARGET) || (r.dia >= DIA_TARGET)).length;
  const pctAbove = (above / total) * 100;

  let pct_acima_alvo_day = "";
  if (above === 0) {
    pct_acima_alvo_day =
      `Data ${key} — 0% acima do alvo: todas as ${total} leituras ficaram dentro de <${SYS_TARGET}/<${DIA_TARGET}.`;
  } else {
    pct_acima_alvo_day =
      `Data ${key} — ${fmt0(pctAbove)}% das leituras (${above}/${total}) ficaram acima do alvo (<${SYS_TARGET}/<${DIA_TARGET}).`;
  }
  pctParts.push(pct_acima_alvo_day);

  // ---- tendencia_diurna (por data)
  const night = rows.filter(r => r.tmin !== null && inWindow(r.tmin, NIGHT_START_MIN, NIGHT_END_MIN));
  const day   = rows.filter(r => r.tmin !== null && !inWindow(r.tmin, NIGHT_START_MIN, NIGHT_END_MIN));

  let tendencia_diurna_day = "";
  if (night.length < 2 || day.length < 2) {
    tendencia_diurna_day =
      `Data ${key} — Tendência diurna: indeterminada (dados insuficientes — dia=${day.length}, noite=${night.length}). ` +
      `(${circadianQualifier})`;
  } else {
    const daySis = mean(day.map(r => r.sis));
    const nightSis = mean(night.map(r => r.sis));
    const dayDia = mean(day.map(r => r.dia));
    const nightDia = mean(night.map(r => r.dia));

    const dropPctSis = ((daySis - nightSis) / daySis) * 100;

    const isNightInTarget = (nightSis < SYS_TARGET) && (nightDia < DIA_TARGET);
    const isDipperProxy = (dropPctSis >= DIPPER_MIN_DROP_PCT) && isNightInTarget;

    tendencia_diurna_day =
      `Data ${key} — Tendência diurna: ${isDipperProxy ? "queda no fim do dia" : "sem queda clara no fim do dia"} — ` +
      `média (dia) ${fmt1(daySis)}/${fmt1(dayDia)} vs média (18–22:59) ${fmt1(nightSis)}/${fmt1(nightDia)} ` +
      `(queda relativa PAS ≈ ${fmt0(dropPctSis)}%). ` +
      `(${circadianQualifier})`;
  }
  tendenciaParts.push(tendencia_diurna_day);

  // ---- pico_matinal_diurno (por data)
  const morning2h = rows.filter(r =>
    r.tmin !== null &&
    r.tmin >= MORNING_START_MIN &&
    r.tmin < (MORNING_START_MIN + 120)
  );

  const morningWide = rows.filter(r =>
    r.tmin !== null &&
    r.tmin >= MORNING_START_MIN &&
    r.tmin < MORNING_END_MIN
  );

  const morningSet = (morning2h.length >= 2) ? morning2h : morningWide;

  const nightSet = rows.filter(r =>
    r.tmin !== null &&
    inWindow(r.tmin, NIGHT_START_MIN, NIGHT_END_MIN)
  );

  let pico_matinal_diurno_day = "";
  if (morningSet.length < 2 || nightSet.length < 1) {
    pico_matinal_diurno_day =
      `Data ${key} — Pico matinal diurno: indeterminado (dados insuficientes — manhã=${morningSet.length}, fim do dia=${nightSet.length}). ` +
      `(${surgeQualifier})`;
  } else {
    const mSis = mean(morningSet.map(r => r.sis));
    const mDia = mean(morningSet.map(r => r.dia));

    // nadir = menor PAS na janela 18–22:59
    let nadir = nightSet[0];
    for (const r of nightSet) {
      if (r.sis < nadir.sis) nadir = r;
    }
    const nadirSis = nadir.sis;
    const nadirDia = nadir.dia;

    const deltaSis = mSis - nadirSis;
    const deltaDia = mDia - nadirDia;

    const surge = (deltaSis >= SURGE_SYS_DELTA) || (deltaDia >= SURGE_DIA_DELTA);

    // pico = maior PAS na manhã escolhida
    let peak = morningSet[0];
    for (const r of morningSet) {
      if (r.sis > peak.sis) peak = r;
    }

    pico_matinal_diurno_day =
      `Data ${key} — Pico matinal diurno: ${surge ? "SIM" : "NÃO"} — ` +
      (surge ? `pico ${fmt0(peak.sis)}/${fmt0(peak.dia)} às ${peak.hora || "—"}; ` : "") +
      `média manhã ${fmt1(mSis)}/${fmt1(mDia)} vs menor (18–22:59) ${fmt0(nadirSis)}/${fmt0(nadirDia)} ` +
      `às ${nadir.hora || "—"} (Δ ${fmt0(deltaSis)}/${fmt0(deltaDia)}). ` +
      `(${surgeQualifier})`;
  }
  picoParts.push(pico_matinal_diurno_day);
}

// ======= 3) SAÍDA FINAL: 1 string por métrica, com todos os dias =======
return [{
  json: {
    media_dia: mediaParts.join(" | "),
    pct_acima_alvo: pctParts.join(" | "),
    tendencia_diurna: tendenciaParts.join(" | "),
    pico_matinal_diurno: picoParts.join(" | "),
  }
}];

// n8n Code node (JavaScript)
// Mode: "Run Once for All Items"
//
// Lê items (linhas) do Sheets (todas as datas),
// classifica por data+horário e inclui a data na saída.
//
// SAÍDA (strings):
// - classifica_por_horario
// - estado_pa

const items = $input.all();

// ---------- helpers ----------
function getField(obj, candidates) {
  if (!obj) return undefined;
  const keys = Object.keys(obj);
  for (const name of candidates) {
    if (obj[name] !== undefined) return obj[name];
    const k = keys.find((kk) => kk.toLowerCase() === String(name).toLowerCase());
    if (k) return obj[k];
  }
  return undefined;
}

function toNumber(v) {
  if (v === null || v === undefined) return NaN;
  if (typeof v === "number") return v;
  const s = String(v).trim().replace(",", ".");
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
}

function pad2(n) {
  return String(n).padStart(2, "0");
}

function parseTimeToSeconds(horaRaw) {
  if (!horaRaw) return NaN;
  const s = String(horaRaw).trim();
  const m = s.match(/(\d{1,2})\D(\d{2})(?:\D(\d{2}))?/);
  if (!m) return NaN;
  const hh = Number(m[1]);
  const mm = Number(m[2]);
  const ss = m[3] !== undefined ? Number(m[3]) : 0;
  if (![hh, mm, ss].every(Number.isFinite)) return NaN;
  return hh * 3600 + mm * 60 + ss;
}

function formatHHMM(horaRaw) {
  const secs = parseTimeToSeconds(horaRaw);
  if (!Number.isFinite(secs)) return String(horaRaw ?? "").trim();
  const hh = Math.floor(secs / 3600);
  const mm = Math.floor((secs % 3600) / 60);
  return `${pad2(hh)}:${pad2(mm)}`;
}

function parseDateKey(dateRaw) {
  if (!dateRaw) return null;

  if (dateRaw instanceof Date && !isNaN(dateRaw.getTime())) {
    const y = dateRaw.getFullYear();
    const m = pad2(dateRaw.getMonth() + 1);
    const d = pad2(dateRaw.getDate());
    return `${y}-${m}-${d}`;
  }

  const s = String(dateRaw).trim();

  // YYYY-MM-DD
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;

  // DD/MM/YYYY or D/M/YY
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (m) {
    const dd = pad2(Number(m[1]));
    const mm = pad2(Number(m[2]));
    let yy = String(m[3]);
    if (yy.length === 2) yy = `20${yy}`;
    return `${yy}-${mm}-${dd}`;
  }

  const t = Date.parse(s);
  if (Number.isFinite(t)) {
    const d = new Date(t);
    const y = d.getFullYear();
    const mo = pad2(d.getMonth() + 1);
    const da = pad2(d.getDate());
    return `${y}-${mo}-${da}`;
  }

  return null;
}

function bpSeverity(sys, dia) {
  let sysLv = 0;
  if (sys >= 180) sysLv = 3;
  else if (sys >= 160) sysLv = 2;
  else if (sys >= 140) sysLv = 1;
  else if (sys >= 130) sysLv = 0.5;
  else if (sys >= 129) sysLv = 0.5;

  let diaLv = 0;
  if (dia >= 110) diaLv = 3;
  else if (dia >= 100) diaLv = 2;
  else if (dia >= 90) diaLv = 1;
  else if (dia >= 88) diaLv = 0.5;

  const level = Math.max(sysLv, diaLv);

  let labelShort = "PA Normal";
  let labelLong = "PA normal (dentro do alvo)";

  if (level === 0.5) {
    labelShort = "PA Levemente alterada";
    labelLong = "PA levemente alterada (fora do alvo)";
  } else if (level === 1) {
    labelShort = "Hipertensão estágio 1";
    labelLong = "HAS estágio 1";
  } else if (level === 2) {
    labelShort = "Hipertensão estágio 2";
    labelLong = "HAS estágio 2";
  } else if (level === 3) {
    labelShort = "Hipertensão estágio 3";
    labelLong = "HAS estágio 3";
  }

  return { level, sysLv, diaLv, labelShort, labelLong };
}

function hrLabel(fc) {
  if (!Number.isFinite(fc)) return "FC: ausente.";
  if (fc < 50) return `FC: ${fc}, Bradicardia.`;
  if (fc <= 89) return `FC: ${fc}, normal e sem marcador de risco cardíaco para paciente em repouso.`;
  if (fc <= 100) return `FC: ${fc}, normal com marcador de risco cardíaco para paciente em repouso. (90–100).`;
  return `FC: ${fc}, Taquicardia (pode sugerir simpático).`;
}

function predominioPorLeitura(sys, dia) {
  const sysHigh = Number.isFinite(sys) ? sys >= 129 : false;
  const diaHigh = Number.isFinite(dia) ? dia >= 88 : false;

  if (sysHigh && diaHigh) return "PA SIS e DIA predominam alta.";
  if (sysHigh) return "PA SIS predomina alta.";
  if (diaHigh) return "PA DIA predomina alta.";
  return "PA dentro do alvo.";
}

// ---------- parse rows ----------
const rows = items.map((it) => it.json ?? {});
const parsed = rows.map((r) => {
  const dataRaw = getField(r, ["data", "Data", "date", "DATA"]);
  const horaRaw = getField(r, ["hora", "Hora", "time", "HORA"]);

  const sysRaw = getField(r, ["pressao_Sis_M", "pressao_SisM", "pressao_Sis", "sis", "PAS"]);
  const diaRaw = getField(r, ["pressao_Dia_M", "pressao_DiaM", "pressao_Dia", "PAD"]);
  const fcRaw  = getField(r, ["pulsacao_M", "pulsacao", "FC", "freq_cardiaca"]);

  const dateKey = parseDateKey(dataRaw);
  const secs = parseTimeToSeconds(horaRaw);

  return {
    dateKey,              // YYYY-MM-DD (normalizado)
    dataRaw,              // original (se quiser usar)
    horaRaw,
    secs,
    sys: toNumber(sysRaw),
    dia: toNumber(diaRaw),
    fc: toNumber(fcRaw),
  };
});

// ---------- usar TODAS as datas ----------
let dayRows = parsed.slice();

if (dayRows.length === 0) {
  return [{ json: { classifica_por_horario: "", estado_pa: "" } }];
}

// ---------- ordena por DATA + horário ----------
dayRows.sort((a, b) => {
  const ad = a.dateKey ? Date.parse(a.dateKey) : Infinity;
  const bd = b.dateKey ? Date.parse(b.dateKey) : Infinity;
  if (ad !== bd) return ad - bd;

  const as = Number.isFinite(a.secs) ? a.secs : 1e12;
  const bs = Number.isFinite(b.secs) ? b.secs : 1e12;
  return as - bs;
});

// ---------- DEDUPLICA por DIA + minuto (YYYY-MM-DD + HH:MM) ----------
const byDayMinute = new Map();
for (const p of dayRows) {
  const hhmm = formatHHMM(p.horaRaw) || String(p.horaRaw ?? "").trim();
  const dkey = p.dateKey || "SEM-DATA";
  const key = `${dkey} ${hhmm}`;
  byDayMinute.set(key, p); // mantém a última leitura daquele minuto naquele dia
}

dayRows = Array.from(byDayMinute.entries())
  .sort((a, b) => {
    const [ad, at] = a[0].split(" ");
    const [bd, bt] = b[0].split(" ");
    const adt = ad === "SEM-DATA" ? Infinity : Date.parse(ad);
    const bdt = bd === "SEM-DATA" ? Infinity : Date.parse(bd);
    if (adt !== bdt) return adt - bdt;
    return parseTimeToSeconds(at) - parseTimeToSeconds(bt);
  })
  .map(([, p]) => p);

// ---------- build outputs (COM DATA) ----------
const classificaParts = [];
const estadoParts = [];

for (const p of dayRows) {
  const hhmm = formatHHMM(p.horaRaw);
  const dataTxt = p.dateKey ? p.dateKey : "sem data";

  const bp = bpSeverity(p.sys, p.dia);
  const hr = hrLabel(p.fc);
  const pred = predominioPorLeitura(p.sys, p.dia);

  classificaParts.push(
    `data: ${dataTxt}; horário de coleta: ${hhmm}; ${bp.labelShort}; ${hr}`
  );

  const valores =
    (Number.isFinite(p.sys) && Number.isFinite(p.dia)) ? ` (${p.sys}/${p.dia})` : "";

  estadoParts.push(
    `data: ${dataTxt}; horário de coleta: ${hhmm}; ${bp.labelLong}${valores}; ${pred}`
  );
}

return [{
  json: {
    classifica_por_horario: classificaParts.join(" | "),
    estado_pa: estadoParts.join(" | "),
  },
}];

