// Timezone
const tz = 'America/Fortaleza';
const agora = new Date();

// ---------- Data atual (YYYY-MM-DD) ----------
const dataAtual = new Intl.DateTimeFormat('pt-BR', {
  timeZone: tz,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
})
  .format(agora)
  .split('/')
  .reverse()
  .join('-');

// ---------- Hora atual (HH:MM:SS) ----------
const horaAtual = new Intl.DateTimeFormat('pt-BR', {
  timeZone: tz,
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
}).format(agora);

// ---------- Dia da semana ----------
const diaSemana = new Intl.DateTimeFormat('pt-BR', {
  timeZone: tz,
  weekday: 'long'
}).format(agora);

// ---------- Lógica original ----------
const linhas = items.map(i => {
  const obj = { ...i.json };

  // Arredonda id_coleta se houver casas decimais
  if (obj.id_coleta !== undefined && obj.id_coleta !== null) {
    obj.id_coleta = Math.round(Number(obj.id_coleta));
  }

  return obj;
});

// Ordena do mais recente para o mais antigo
linhas.sort((a, b) => Number(b.id_coleta) - Number(a.id_coleta));

// Pega a mais nova e a penúltima (anterior)
const ultima = linhas[0] || null;
const penultima = linhas[1] || null;

// Se não tiver nenhuma linha, retorna vazio
if (!ultima) return [];

// Acrescenta data, hora e dia da semana (na última)
ultima.data_atual = dataAtual;
ultima.hora_atual = horaAtual;
ultima.dia_semana = diaSemana;

// Anexa a penúltima para comparação no agente
// (mantém a estrutura principal e entrega o "anterior" dentro do objeto)
ultima.anterior = penultima;

// Retorna para os próximos nós
return [{ json: ultima }];

// n8n Code node (JavaScript)
// Mode: "Run Once for All Items"
//
// Entrada: várias linhas do Google Sheets (items), com pelo menos:
// - uma coluna de data (ex: "data" / "date" / "data_coleta")
// - uma coluna de hora (ex: "hora" / "horario" / "time") no formato HH:MM ou HH:MM:SS
//
// Saída: 1 item com o diagnóstico das coletas do dia mais recente.

const TZ = "America/Fortaleza";

// Ajuste aqui se seus nomes de colunas forem diferentes:
const DATE_KEYS = ["data", "date", "Data", "DATA", "data_coleta", "dia"];
const TIME_KEYS = ["hora", "Hora", "time", "Time", "horario", "horário"];

// Janelas (minutos desde 00:00). Fim inclusivo.
const WINDOWS = [
  { id: 1, start: 5 * 60 + 0,  end: 8 * 60 + 59,  label: "1º (05:00–08:59) — após acordar" },
  { id: 2, start: 9 * 60 + 0,  end: 11 * 60 + 59, label: "2º (09:00–11:59) — antes do almoço" },
  { id: 3, start: 12 * 60 + 0, end: 13 * 60 + 59, label: "3º (12:00–13:59) — depois do almoço" },
  { id: 4, start: 14 * 60 + 0, end: 17 * 60 + 59, label: "4º (14:00–17:59) — antes da janta" },
  { id: 5, start: 18 * 60 + 0, end: 19 * 60 + 59, label: "5º (18:00–19:59) — depois da janta" },
  { id: 6, start: 20 * 60 + 0, end: 23 * 60 + 59, label: "6º (20:00–23:59) — antes de dormir" },
];

function pickField(obj, keys) {
  for (const k of keys) {
    if (obj?.[k] !== undefined && obj?.[k] !== null && String(obj[k]).trim() !== "") return k;
  }
  return null;
}

function parseDateToISO(raw) {
  if (!raw) return null;
  const s = String(raw).trim();

  // YYYY-MM-DD
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;

  // DD/MM/YYYY (ou DD-MM-YYYY)
  const br = s.match(/^(\d{2})[\/-](\d{2})[\/-](\d{4})$/);
  if (br) return `${br[3]}-${br[2]}-${br[1]}`;

  // Se vier como Date/serial/ISO completo, tenta Date()
  const d = new Date(s);
  if (!isNaN(d.getTime())) {
    // converte para data no TZ
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: TZ,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(d);
    const get = (t) => parts.find(p => p.type === t)?.value;
    return `${get("year")}-${get("month")}-${get("day")}`;
  }

  return null;
}

function timeToMinutes(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (!m) return null;
  const hh = Number(m[1]);
  const mm = Number(m[2]);
  const ss = m[3] ? Number(m[3]) : 0;
  if (hh < 0 || hh > 23 || mm < 0 || mm > 59 || ss < 0 || ss > 59) return null;
  return hh * 60 + mm + (ss / 60);
}

function fmtNowTZ() {
  const d = new Date();
  const dateParts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit"
  }).formatToParts(d);
  const timeParts = new Intl.DateTimeFormat("en-GB", {
    timeZone: TZ, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false
  }).formatToParts(d);

  const get = (parts, t) => parts.find(p => p.type === t)?.value;

  const yyyy = get(dateParts, "year");
  const MM = get(dateParts, "month");
  const dd = get(dateParts, "day");

  const HH = get(timeParts, "hour");
  const mm = get(timeParts, "minute");
  const ss = get(timeParts, "second");

  const nowDateISO = `${yyyy}-${MM}-${dd}`;
  const nowTime = `${HH}:${mm}:${ss}`;
  const nowMin = Number(HH) * 60 + Number(mm) + (Number(ss) / 60);

  return { nowDateISO, nowTime, nowMin };
}

// -------------------- MAIN --------------------
const items = $input.all().map(i => i.json ?? {});
if (!items.length) {
  return [{ json: { ok: false, erro: "Nenhuma linha recebida do Sheets." } }];
}

const sample = items[0];
const dateKey = pickField(sample, DATE_KEYS) || pickField(items.find(x => pickField(x, DATE_KEYS)) || {}, DATE_KEYS);
const timeKey = pickField(sample, TIME_KEYS) || pickField(items.find(x => pickField(x, TIME_KEYS)) || {}, TIME_KEYS);

if (!dateKey || !timeKey) {
  return [{
    json: {
      ok: false,
      erro: "Não encontrei automaticamente as colunas de data/hora.",
      dica: "Edite DATE_KEYS e TIME_KEYS para bater com o nome das colunas do seu sheet.",
      encontrado: { dateKey, timeKey, colunas_exemplo: Object.keys(sample) }
    }
  }];
}

// Normaliza datas e descarta linhas sem data/hora válidas
const normalized = items
  .map((row, idx) => {
    const dateISO = parseDateToISO(row[dateKey]);
    const tMin = timeToMinutes(row[timeKey]);
    return {
      idx,
      raw: row,
      dateISO,
      timeStr: row[timeKey] != null ? String(row[timeKey]).trim() : "",
      tMin
    };
  })
  .filter(r => r.dateISO && r.tMin != null);

if (!normalized.length) {
  return [{
    json: {
      ok: false,
      erro: "As linhas recebidas não têm data/hora válidas (ou formato inesperado).",
      dateKey,
      timeKey
    }
  }];
}

// Descobre a data mais recente
const latestDateISO = normalized
  .map(r => r.dateISO)
  .reduce((max, cur) => (cur > max ? cur : max), normalized[0].dateISO);

// Filtra só a data mais recente
const latestRows = normalized.filter(r => r.dateISO === latestDateISO);

// Lista de horários coletados (ordenados)
const collected = latestRows
  .map(r => ({ timeStr: r.timeStr, tMin: r.tMin }))
  .sort((a, b) => a.tMin - b.tMin);

const { nowDateISO, nowTime, nowMin } = fmtNowTZ();

// Classifica janelas
const detail = WINDOWS.map(w => {
  const hits = collected
    .filter(c => c.tMin >= w.start && c.tMin <= w.end)
    .map(c => c.timeStr);

  const state =
    nowMin > w.end ? "encerrada" :
    (nowMin >= w.start && nowMin <= w.end) ? "em_andamento" :
    "futura";

  const done = hits.length > 0;

  return {
    coleta: w.id,
    janela: w.label,
    estado_janela: state,     // encerrada | em_andamento | futura
    feita: done,
    horarios_encontrados: hits
  };
});

// Regras:
// - "perdida": janela encerrada e não feita
// - "em_aberto": janela em_andamento e não feita (ainda dá tempo)
// - "futuras": ainda não começou
const perdidas = detail.filter(d => d.estado_janela === "encerrada" && !d.feita).map(d => d.coleta);
