const TZ = "America/Fortaleza";

const WINDOWS = [
  { id: 1, janela: "05:00–08:59", desc: "após acordar" },
  { id: 2, janela: "09:00–11:59", desc: "antes do almoço" },
  { id: 3, janela: "12:00–13:59", desc: "depois do almoço" },
  { id: 4, janela: "14:00–17:59", desc: "antes da janta" },
  { id: 5, janela: "18:00–19:59", desc: "depois da janta" },
  { id: 6, janela: "20:00–23:59", desc: "antes de dormir" },
];

function pickMainItem(items) {
  return items.find(i => i?.json?.ok === true)?.json ?? items[0]?.json ?? {};
}

function parseHour(hhmmss) {
  if (!hhmmss) return null;
  const m = String(hhmmss).trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (!m) return null;
  const hh = Number(m[1]);
  if (!Number.isFinite(hh)) return null;
  return hh;
}

function saudacaoPorHora(h) {
  if (h === null) return "Olá";
  if (h >= 5 && h <= 11) return "Bom dia";
  if (h >= 12 && h <= 17) return "Boa tarde";
  return "Boa noite";
}

const ORD_MASC = ["", "primeiro", "segundo", "terceiro", "quarto", "quinto", "sexto", "sétimo", "oitavo", "nono", "décimo"];
const ORD_FEM  = ["", "primeira", "segunda", "terceira", "quarta", "quinta", "sexta", "sétima", "oitava", "nona", "décima"];

function ordinalExtenso(n, feminino = false) {
  const k = Number(n);
  if (Number.isInteger(k) && k >= 1 && k <= 10) return (feminino ? ORD_FEM : ORD_MASC)[k];
  return `${k}º`;
}

function ordinalSimbolo(n) {
  const k = Number(n);
  return Number.isFinite(k) ? `${k}º` : "";
}

function fmtBRDate(iso) {
  if (!iso) return "";
  const m = String(iso).trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return String(iso);
  return `${m[3]}/${m[2]}/${m[1]}`;
}

function diffDays(isoA, isoB) {
  const ma = String(isoA || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const mb = String(isoB || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!ma || !mb) return null;
  const a = new Date(Date.UTC(Number(ma[1]), Number(ma[2]) - 1, Number(ma[3])));
  const b = new Date(Date.UTC(Number(mb[1]), Number(mb[2]) - 1, Number(mb[3])));
  return Math.round((b - a) / (1000 * 60 * 60 * 24));
}

function formatQuando(dataMed, horaMed, dataAtual) {
  const d = diffDays(dataMed, dataAtual);
  if (d === 0) return `hoje às ${horaMed || "—"}`;
  if (d === 1) return `ontem às ${horaMed || "—"}`;
  if (d !== null && d > 1) return `em ${fmtBRDate(dataMed)} às ${horaMed || "—"}`;
  if (dataMed && horaMed) return `em ${fmtBRDate(dataMed)} às ${horaMed}`;
  if (horaMed) return `às ${horaMed}`;
  if (dataMed) return `em ${fmtBRDate(dataMed)}`;
  return "";
}

// ✅ AJUSTE CRÍTICO: não transformar "" em 0
function safeNum(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (s === "") return null;             // <-- aqui está o conserto
  const n = Number(s.replace(",", "."));
  return Number.isFinite(n) ? n : null;
}

function classifyBP(sys, dia) {
  if (sys == null || dia == null) return { label: "indisponível", grau: 0 };

  if (sys < 129 && dia < 88) return { label: "Normal", grau: 0 };
  if (sys >= 180 || dia >= 110) return { label: "Hipertensão estágio 3 (grave)", grau: 3 };
  if ((sys >= 160 && sys <= 179) || (dia >= 100 && dia <= 109)) return { label: "Hipertensão estágio 2", grau: 2 };
  if ((sys >= 140 && sys <= 159) || (dia >= 90 && dia <= 99)) return { label: "Hipertensão estágio 1", grau: 1 };
  if (sys >= 130 && sys <= 139 && dia < 89) return { label: "Levemente alterada", grau: 0.5 };

  return { label: "Pressão alterada (fora do alvo)", grau: 0.5 };
}

function comentarioComponente(sys, dia) {
  const maxAlta = sys != null && sys >= 130;
  const minAlta = dia != null && dia >= 89;

  if (maxAlta && minAlta) return "com aumento na pressão máxima e mínima";
  if (maxAlta) return "com leve aumento na pressão máxima";
  if (minAlta) return "com leve aumento na pressão mínima";
  return "dentro do esperado";
}

function findColetaAtual(payload) {
  const emAberto = Array.isArray(payload.em_aberto) ? payload.em_aberto : [];
  if (emAberto.length) return { id: emAberto[0], motivo: "em_aberto" };

  const details = Array.isArray(payload.detalhes_por_coleta) ? payload.detalhes_por_coleta : [];
  const current = details.find(d => d.estado_janela === "em_andamento");

  if (current) {
    if (!current.feita) return { id: current.coleta, motivo: "janela_atual" };
    const next = details.find(d => d.estado_janela === "futura" && !d.feita);
    if (next) return { id: next.coleta, motivo: "proxima_pendente" };
    return { id: current.coleta, motivo: "todas_feitas_ou_adiantadas" };
  }

  return { id: null, motivo: "indefinida" };
}

function missedText(perdidas) {
  if (!perdidas.length) return "";
  const parts = perdidas.map(id => {
    const w = WINDOWS.find(x => x.id === id);
    if (!w) return `${ordinalSimbolo(id)} coleta`;
    return `${ordinalSimbolo(id)} coleta (entre ${w.janela}, ${w.desc})`;
  });

  if (parts.length === 1) return `Notei que a ${parts[0]} não foi realizada.`;
  return `Notei que as seguintes coletas não foram realizadas: ${parts.join(", ")}.`;
}

