// -------- Helpers --------
function isEmpty(v) {
  return v === null || v === undefined || String(v).trim() === "";
}

function toInt(v) {
  if (isEmpty(v)) return null;
  const n = Number(String(v).trim());
  return Number.isFinite(n) ? Math.trunc(n) : null;
}

function firstEmptyTrioIndex(j) {
  // retorna 1,2,3 ou null se todos completos
  for (let x = 1; x <= 3; x++) {
    const sis = j[`pressao_Sis${x}`];
    const dia = j[`pressao_Dia${x}`];
    const pul = j[`pulsacao${x}`];
    if (isEmpty(sis) && isEmpty(dia) && isEmpty(pul)) return x; // trio totalmente vazio
  }
  // se existir trio parcialmente preenchido (não deveria, mas por segurança):
  for (let x = 1; x <= 3; x++) {
    const sis = j[`pressao_Sis${x}`];
    const dia = j[`pressao_Dia${x}`];
    const pul = j[`pulsacao${x}`];
    if (isEmpty(sis) || isEmpty(dia) || isEmpty(pul)) return x;
  }
  return null;
}

function lastFilledTrioBefore(j, x) {
  // procura o último trio completo anterior a x (x-1, x-2...)
  for (let k = x - 1; k >= 1; k--) {
    const sis = toInt(j[`pressao_Sis${k}`]);
    const dia = toInt(j[`pressao_Dia${k}`]);
    const pul = toInt(j[`pulsacao${k}`]);
    if (sis != null && dia != null && pul != null) return { k, sis, dia, pul };
  }
  return null;
}

function hasLetters(msg) {
  // Se tiver qualquer letra (inclui acentos), pede para enviar só números
  return /[A-Za-zÀ-ÖØ-öø-ÿ]/.test(msg);
}

function parseMeasurement(message) {
  const msg = String(message ?? "").trim();

  // Regra: se houver letras, rejeita (mesmo se tiver números)
  if (hasLetters(msg)) {
    return {
      ok: false,
      reason: "letters",
      missing: [],
      parsed: null,
    };
  }

  // Pressão: 3 dígitos / 2 dígitos (ex.: 130/90), aceitando / x por
  // Observação: "por" já seria letra, então pela sua regra será rejeitado.
  // Então aceitamos apenas separadores sem letras: "/" ou "x" (sem espaços) e também "130 90" NÃO (evita ambiguidade)
  // Mas você pediu aceitar "130x90"; para "130 por 90" teria letras -> rejeita.
  const bp = msg.match(/(\d{3})\s*(\/|x)\s*(\d{2,3})/);
  if (!bp) {
    // se não bateu padrão de PA, tenta dizer que faltou PA
    return {
      ok: false,
      reason: "no_bp_pattern",
      missing: ["pressao_sis_diast"],
      parsed: null,
    };
  }

  const sys = Number(bp[1]);
  const dia = Number(bp[3]);

  // Pulsação: procurar um número de 2 ou 3 dígitos que NÃO seja sys/dia e esteja fora do trecho já capturado
  // Estratégia simples: pega todos números e remove sys e dia (uma ocorrência cada), o próximo é pulso.
  const nums = (msg.match(/\d+/g) || []).map(n => Number(n));

  // remove 1 ocorrência de sys e dia
  function removeOnce(arr, val) {
    const idx = arr.indexOf(val);
    if (idx >= 0) arr.splice(idx, 1);
  }
  const rest = nums.slice();
  removeOnce(rest, sys);
  removeOnce(rest, dia);

  // pulso: escolha o primeiro número plausível 30..220
  const pul = rest.find(n => Number.isFinite(n) && n >= 30 && n <= 220) ?? null;

  const missing = [];
  if (!Number.isFinite(sys)) missing.push("sis");
  if (!Number.isFinite(dia)) missing.push("dia");
  if (pul == null) missing.push("puls");

  if (missing.length) {
    return {
      ok: false,
      reason: "incomplete",
      missing,
      parsed: { sys: Number.isFinite(sys) ? sys : null, dia: Number.isFinite(dia) ? dia : null, pul },
    };
  }

  // Validação: sistólica deve ter 3 dígitos (100..250) e diastólica 2-3 dígitos (50..150)
  if (!(sys >= 100 && sys <= 250)) {
    return { ok: false, reason: "sys_out_of_range", missing: [], parsed: null };
  }
  if (!(dia >= 50 && dia <= 150)) {
    return { ok: false, reason: "dia_out_of_range", missing: [], parsed: null };
  }

  return { ok: true, reason: "ok", missing: [], parsed: { sys, dia, pul } };
}

function msgAskNumbersOnly() {
  return (
    "Não consegui registrar porque sua mensagem contém letras. " +
    "Por favor, envie **somente números** neste formato:\n" +
    "• 130/90 80\n" +
    "ou\n" +
    "• 130x90 80\n" +
    "(pressão sistólica/diastólica e depois a pulsação)."
