}

function msgAskComplete(missing) {
  const map = {
    sis: "pressão sistólica (ex.: 130)",
    dia: "pressão diastólica (ex.: 90)",
    puls: "pulsação (ex.: 80)",
    pressao_sis_diast: "pressão no formato 3 dígitos/2–3 dígitos (ex.: 130/90)",
  };

  const parts = missing.map(k => map[k] || k);
  return (
    "Os dados vieram incompletos. Faltou: " + parts.join(", ") + ".\n" +
    "Envie neste formato (somente números):\n" +
    "• 130/90 80\n" +
    "ou\n" +
    "• 130x90 80"
  );
}

function msgDeltaTooHigh(prev, cur) {
