  // Já tem 3 medições
  out.stat_medi = "triagem";
  out.mensagem_usuario = "Coletas concluídas para este período ✅";
  return [{ json: out }];
}

// Parse
const parsed = parseMeasurement(msg);

if (!parsed.ok) {
  if (parsed.reason === "letters") {
    out.mensagem_usuario = msgAskNumbersOnly();
    return [{ json: out }];
  }
  if (parsed.reason === "incomplete") {
    out.mensagem_usuario = msgAskComplete(parsed.missing);
    return [{ json: out }];
  }
  if (parsed.reason === "no_bp_pattern") {
    out.mensagem_usuario = msgAskComplete(["pressao_sis_diast", "puls"]);
    return [{ json: out }];
  }
  if (parsed.reason === "sys_out_of_range" || parsed.reason === "dia_out_of_range") {
    out.mensagem_usuario =
      "Os valores parecem fora do esperado. Envie novamente (somente números) no formato: 130/90 80.";
    return [{ json: out }];
  }

  out.mensagem_usuario = "Não consegui entender. Envie no formato: 130/90 80 (somente números).";
  return [{ json: out }];
}

// Delta validation vs previous filled trio
const prev = lastFilledTrioBefore(out, slot);
if (prev) {
  const dSys = Math.abs(parsed.parsed.sys - prev.sis);
  const dDia = Math.abs(parsed.parsed.dia - prev.dia);
  if (dSys > 15 || dDia > 15) {
    out.mensagem_usuario = msgDeltaTooHigh(prev, parsed.parsed);
    return [{ json: out }];
  }
}

// Fill the slot
out[`pressao_Sis${slot}`] = String(parsed.parsed.sys);
out[`pressao_Dia${slot}`] = String(parsed.parsed.dia);
out[`pulsacao${slot}`]    = String(parsed.parsed.pul);

// Update status + user message
if (slot === 3) {
  out.stat_medi = "triagem";
  out.mensagem_usuario = "Coletas concluídas para este período ✅";
} else {
  out.mensagem_usuario = msgNext(slot);
}

return [{ json: out }];

// n8n Code node (JavaScript)
// Mode: Run Once for All Items

const j = $input.all()[0]?.json ?? {};

function toNum(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().replace(",", ".");
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

// ---------- pega valores (flexível) ----------
function pick(pathArr, fallback = null) {
  for (const p of pathArr) {
    try {
      // navega path tipo ["anterior","pressao_Sis_M"]
      let cur = j;
      for (const k of p) cur = cur?.[k];
      const n = toNum(cur);
      if (n !== null) return n;
    } catch {}
  }
  return fallback;
}

// Atual: tenta (atual.sis) -> (pressao_Sis_M) -> (pressao_Sis1)
const sysA = pick([["atual","sis"], ["pressao_Sis_M"], ["pressao_Sis1"]]);
const diaA = pick([["atual","dia"], ["pressao_Dia_M"], ["pressao_Dia1"]]);
const pulA = pick([["atual","puls"], ["pulsacao_M"],   ["pulsacao1"]]);

// Última: tenta (ultima.sis) -> (anterior.pressao_Sis_M) -> (anterior.pressao_Sis1)
const sysU = pick([["ultima","sis"], ["anterior","pressao_Sis_M"], ["anterior","pressao_Sis1"]]);
const diaU = pick([["ultima","dia"], ["anterior","pressao_Dia_M"], ["anterior","pressao_Dia1"]]);
const pulU = pick([["ultima","puls"],["anterior","pulsacao_M"],    ["anterior","pulsacao1"]]);

// ---------- valida ----------
if ([sysA,diaA,pulA,sysU,diaU,pulU].some(v => v === null)) {
  return [{
    json: {
      ok: false,
      erro: "Dados insuficientes para comparação (verifique se existem valores atuais e anteriores).",
      debug: {
        lidos: { sysA, diaA, pulA, sysU, diaU, pulU },
        esperado_1: "j.atual{sis,dia,puls} e j.ultima{sis,dia,puls}",
        esperado_2: "pressao_*_M e anterior.pressao_*_M"
      }
    }
  }];
}

// ---------- parâmetros ----------
const EPS_SYS = 5;
const EPS_DIA = 3;
const EPS_PUL = 5;

// ---------- classificação PA ----------
function classPA(sys, dia) {
  if (sys >= 180 || dia >= 110) return "HAS estágio 3";
  if ((sys >= 160 && sys <= 179) || (dia >= 100 && dia <= 109)) return "HAS estágio 2";
  if ((sys >= 140 && sys <= 159) || (dia >= 90 && dia <= 99)) return "HAS estágio 1";
  if (sys >= 130 && sys <= 139 && dia < 89) return "Levemente alterada";
  if (sys < 129 && dia < 88) return "Normal";
  return "Alterada (fora do alvo)";
}

// ---------- FC ----------
function classFC(p) {
  if (p < 50) return "Bradicardia";
  if (p > 101) return "Taquicardia";
  if (p >= 90 && p <= 100) return "Normal (90–100: atenção)";
  return "Normal";
}

function deltaDir(delta, eps) {
  if (Math.abs(delta) <= eps) return { dir: "estável", significant: false };
  return { dir: delta > 0 ? "aumentou" : "reduziu", significant: true };
}

function pattern(paDir, fcDir) {
  if (paDir === "aumentou" && fcDir === "aumentou") return "PA↑ + FC↑ → simpático (ansiedade/dor/exercício/estimulantes)";
  if (paDir === "aumentou" && (fcDir === "estável" || fcDir === "reduziu")) return "PA↑ + FC normal/↓ → hipertensão sustentada/sobrecarga volêmica";
  if (paDir === "reduziu" && fcDir === "aumentou") return "PA↓ + FC↑ → vasodilatação/desidratação/reflexo";
  if (paDir === "reduziu" && (fcDir === "estável" || fcDir === "reduziu")) return "PA↓ + FC↓ → normotenso/efeito de betabloqueador (se usa)";
  return "padrão misto/indefinido";
}

// ---------- deltas ----------
const dSys = sysA - sysU;
const dDia = diaA - diaU;
const dPul = pulA - pulU;

const sysDir = deltaDir(dSys, EPS_SYS);
const diaDir = deltaDir(dDia, EPS_DIA);
const pulDir = deltaDir(dPul, EPS_PUL);

// direção global da PA
let paDir = "estável";
let comp = "SIS/DIA";
if (!sysDir.significant && !diaDir.significant) {
  paDir = "estável";
} else if (sysDir.significant && !diaDir.significant) {
  paDir = sysDir.dir; comp = "SIS";
} else if (!sysDir.significant && diaDir.significant) {
  paDir = diaDir.dir; comp = "DIA";
} else if (sysDir.dir === diaDir.dir) {
  paDir = sysDir.dir; comp = "SIS e DIA";
} else {
  paDir = "misto"; comp = "SIS vs DIA";
}

const clsA = classPA(sysA, diaA);
const clsU = classPA(sysU, diaU);
const fcA  = classFC(pulA);
const fcU  = classFC(pulU);

// resumo
let resumo = `A PA variou de ${sysU}/${diaU} para ${sysA}/${diaA}. `;
if (paDir === "estável") {
  resumo += "Variações pequenas (clinicamente pouco relevantes): pressão considerada **estável**. ";
} else if (paDir === "misto") {
  resumo += `Mudança **mista** (SIS e DIA em direções diferentes). `;
} else {
  resumo += `Houve ${paDir} significativo em ${comp}. `;
}
resumo += `Classificação atual: **${clsA}** (antes: ${clsU}). `;
resumo += `FC: ${pulU} → ${pulA} bpm (${pulDir.dir}). FC atual: **${fcA}** (antes: ${fcU}). `;

let paForPattern = paDir === "misto" ? (sysDir.significant ? sysDir.dir : "estável") : paDir;
resumo += pattern(paForPattern, pulDir.dir);

return [{
  json: {
    ok: true,
    resumo,
    atual: { sis: sysA, dia: diaA, puls: pulA, class_pa: clsA, class_fc: fcA },
    ultima: { sis: sysU, dia: diaU, puls: pulU, class_pa: clsU, class_fc: fcU },
    deltas: { sis: dSys, dia: dDia, puls: dPul, pa_dir: paDir, fc_dir: pulDir.dir }
  }
}];
